select n.nspname||'.'||c.relname as fq, c.relkind, c.relrowsecurity as rls, has_table_privilege('authenticated', c.oid, 'SELECT') as a_sel, has_table_privilege('authenticated', c.oid, 'INSERT') as a_ins, has_table_privilege('authenticated', c.oid, 'UPDATE') as a_upd, has_table_privilege('authenticated', c.oid, 'DELETE') as a_del, has_any_column_privilege('authenticated', c.oid, 'SELECT') as a_col_sel, has_any_column_privilege('authenticated', c.oid, 'UPDATE') as a_col_upd, has_table_privilege('anon', c.oid, 'SELECT') as anon_sel, (select count(*) from pg_policy where polrelid=c.oid) as policies, c.reloptions, obj_description(c.oid,'pg_class') as comentario from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('crm','private','public') and c.relkind in ('r','v','m','p') order by 1
